-- 0014_default_bookmarks: give existing profiles with no bookmarks the default set
-- (same list as cm_core::default_bookmarks; a test keeps them equal).
UPDATE profiles
SET settings = json_set(settings, '$.bookmarks', json('[{"title":"Facebook","url":"https://www.facebook.com/","folder":"Facebook"},{"title":"Notifications","url":"https://www.facebook.com/settings?tab=notifications","folder":"Facebook"},{"title":"Account Quality","url":"https://www.facebook.com/accountquality","folder":"Facebook"},{"title":"Ads Manager","url":"https://www.facebook.com/adsmanager/manage/campaigns","folder":"Facebook"},{"title":"Billing","url":"https://www.facebook.com/ads/manager/account_settings/account_billing","folder":"Facebook"},{"title":"Business Manager","url":"https://business.facebook.com/select","folder":"Facebook"},{"title":"Amazon","url":"https://www.amazon.com/","folder":"Dropshipping"},{"title":"eBay","url":"https://ebay.com/","folder":"Dropshipping"},{"title":"Walmart","url":"https://walmart.com/","folder":"Dropshipping"},{"title":"Shopify","url":"https://www.shopify.com/","folder":"Dropshipping"},{"title":"Taobao","url":"https://taobao.com/","folder":"Dropshipping"},{"title":"Aliexpress","url":"https://aliexpress.com/","folder":"Dropshipping"},{"title":"PayPal","url":"https://paypal.com/","folder":"Dropshipping"},{"title":"Payoneer","url":"https://payoneer.com/","folder":"Dropshipping"},{"title":"Coinlist","url":"https://coinlist.co/","folder":"Crypto"},{"title":"Huobi","url":"https://www.huobi.com/","folder":"Crypto"},{"title":"Discord","url":"https://discord.com/","folder":"Crypto"},{"title":"Premint","url":"https://www.premint.xyz/","folder":"Crypto"},{"title":"Facebook","url":"https://www.facebook.com/","folder":null},{"title":"Amazon","url":"https://www.amazon.com/","folder":null},{"title":"TikTok","url":"https://www.tiktok.com/","folder":null},{"title":"Google Ads","url":"https://ads.google.com/","folder":null},{"title":"Browser check","url":"https://iphey.com/","folder":null}]'))
WHERE json_array_length(coalesce(json_extract(settings, '$.bookmarks'), '[]')) = 0;
